const q = ($input.first().json.query) || {};
const email = String(q.email || '').trim().toLowerCase();
const code = String(q.code || '').trim();
const company = String(q.company || '').trim();
return [{ json: { email, code, company } }];

const req = $('تجهيز الطلب').first().json;
const res = $input.first().json || {};
const results = res.results || [];
const codeOf = (pg) => {
  const cp = ((pg.properties || {})['رمز الدخول'] || {});
  return (cp.rich_text && cp.rich_text[0] && cp.rich_text[0].plain_text) || '';
};
const nameOf = (pg) => {
  const t = ((pg.properties || {})['المنشأة'] || {});
  return (t.title && t.title.map(x => x.plain_text).join('')) || '';
};
const rows = results.filter(pg => { const sc = codeOf(pg); return !!sc && sc === req.code; });
if (!req.email || !req.code || !rows.length) {
  return [{ json: { valid: false, email: req.email } }];
}
const companies = rows.map(pg => ({ pageId: pg.id, name: nameOf(pg) }));
let page = rows[0];
if (req.company) {
  const want = req.company.replace(/-/g, '');
  const m = rows.find(pg => pg.id.replace(/-/g, '') === want);
  if (m) page = m;
}
const p = page.properties || {};
const companyName = nameOf(page);
const g = (name, kind) => {
  const v = p[name] || {};
  if (kind === 'number') return typeof v.number === 'number' ? v.number : null;
  if (kind === 'select') return (v.select && v.select.name) || null;
  if (kind === 'date') return (v.date && v.date.start) || null;
  if (kind === 'text') return (v.rich_text && v.rich_text.map(x => x.plain_text).join('')) || '';
  return null;
};
const subStatus = g('حالة الاشتراك', 'select');
const locked = subStatus !== null && subStatus !== 'نشط';
return [{ json: {
  valid: true, locked, company: companyName, email: req.email, pageId: page.id,
  companies,
  employees: g('عدد الموظفين', 'number'),
  saudis: g('عدد السعوديين', 'number'),
  band: g('النطاق المتوقع', 'select'),
  quarterlyCost: g('التكلفة الربعية التقديرية', 'number'),
  annualCost: g('التكلفة السنوية التقديرية', 'number'),
  lastAnalysis: g('آخر تحليل', 'date'),
  status: g('الحالة', 'select'),
  summary: g('ملخص الوكيل', 'text'),
} }];

const auth = $('تحقق رمز الدخول').first().json;
const regRes = ($('جلب سجل الامتثال').first().json || {}).results || [];
const alertRes = ($('جلب التنبيهات').first().json || {}).results || [];
const docsRes = ($input.first().json || {}).results || [];
const today = new Date().toISOString().slice(0,10);
const daysBetween = (a, b) => Math.round((new Date(a) - new Date(b)) / 86400000);

const register = regRes.map(pg => {
  const p = pg.properties || {};
  const platform = (p['المنصة'] && p['المنصة'].select && p['المنصة'].select.name) || '';
  const subject = (p['الموظف أو الموضوع'] && p['الموظف أو الموضوع'].rich_text && p['الموظف أو الموضوع'].rich_text.map(x=>x.plain_text).join('')) || '';
  const expiry = (p['تاريخ الانتهاء'] && p['تاريخ الانتهاء'].date && p['تاريخ الانتهاء'].date.start) || null;
  const actionType = (p['نوع الإجراء'] && p['نوع الإجراء'].select && p['نوع الإجراء'].select.name) || '';
  const days = expiry ? daysBetween(expiry, today) : null;
  return { platform, subject, expiry, actionType, daysRemaining: days };
}).sort((a,b) => (a.daysRemaining ?? 99999) - (b.daysRemaining ?? 99999));

const alerts = alertRes.map(pg => {
  const p = pg.properties || {};
  const title = (p['التنبيه'] && p['التنبيه'].title && p['التنبيه'].title.map(x=>x.plain_text).join('')) || '';
  const risk = (p['الخطورة'] && p['الخطورة'].select && p['الخطورة'].select.name) || '';
  const platform = (p['المنصة'] && p['المنصة'].select && p['المنصة'].select.name) || '';
  const days = typeof (p['الأيام المتبقية'] && p['الأيام المتبقية'].number) === 'number' ? p['الأيام المتبقية'].number : null;
  const action = (p['الإجراء الموصى به'] && p['الإجراء الموصى به'].rich_text && p['الإجراء الموصى به'].rich_text.map(x=>x.plain_text).join('')) || '';
  const approval = (p['الموافقة البشرية'] && p['الموافقة البشرية'].select && p['الموافقة البشرية'].select.name) || '';
  const expiry = (p['تاريخ الانتهاء'] && p['تاريخ الانتهاء'].date && p['تاريخ الانتهاء'].date.start) || null;
  return { title, risk, platform, daysRemaining: days, action, approval, expiry };
});

const files = docsRes.map(pg => {
  const p = pg.properties || {};
  const gt = (n) => ((p[n] || {}).rich_text || []).map(x => x.plain_text).join('');
  const name = ((p['Document Name'] || {}).title || []).map(x => x.plain_text).join('');
  const type = ((p['Document Type'] || {}).select || {}).name || '';
  const uploaded = (((p['Uploaded Date'] || {}).date) || {}).start || null;
  const expiry = (((p['Expiry Date'] || {}).date) || {}).start || null;
  const conf = typeof (p['Confidence'] || {}).number === 'number' ? p['Confidence'].number : null;
  const review = !!((p['Needs Human Review'] || {}).checkbox);
  return { docId: pg.id, name, type, uploaded, expiry, confidence: conf, needsReview: review, driveFileId: gt('Drive File ID'), url: ((p['File URL'] || {}).url) || null };
}).filter(f => f.driveFileId);

const riskRank = { 'أحمر': 0, 'أصفر': 1, 'أخضر': 2 };
alerts.sort((a,b) => (riskRank[a.risk] ?? 3) - (riskRank[b.risk] ?? 3));

const redCount = alerts.filter(a => a.risk === 'أحمر').length;
const yellowCount = alerts.filter(a => a.risk === 'أصفر').length;
const greenCount = alerts.filter(a => a.risk === 'أخضر').length;

const expiredCount = register.filter(r => r.daysRemaining !== null && r.daysRemaining <= 0).length;
const soonCount = register.filter(r => r.daysRemaining !== null && r.daysRemaining > 0 && r.daysRemaining <= 30).length;
let score = 100 - (redCount * 20) - (yellowCount * 8) - (greenCount * 2) - (expiredCount * 15) - (soonCount * 5);
if (score < 0) score = 0;
if (score > 100) score = 100;
let band = 'ممتاز'; if (score < 40) band = 'خطر'; else if (score < 65) band = 'بحاجة متابعة'; else if (score < 85) band = 'جيد';

const PLATFORM_DEFS = [
  { key: 'sbc', label: 'المركز السعودي للأعمال', authority: 'وزارة التجارة', match: 'المركز السعودي للأعمال' },
  { key: 'cr', label: 'السجل التجاري', authority: 'وزارة التجارة', match: 'السجل التجاري' },
  { key: 'chamber', label: 'الغرفة التجارية', authority: 'الغرف التجارية', match: 'الغرفة التجارية' },
  { key: 'address', label: 'العنوان الوطني', authority: 'البريد السعودي', match: 'العنوان الوطني' },
  { key: 'qiwa', label: 'قوى', authority: 'HRSD', match: 'قوى' },
  { key: 'muqeem', label: 'مقيم', authority: 'الجوازات', match: 'مقيم' },
  { key: 'mudad', label: 'مدد', authority: 'HRSD', match: 'مدد' },
  { key: 'gosi', label: 'التأمينات (GOSI)', authority: 'GOSI', match: 'GOSI' },
  { key: 'zatca', label: 'الزكاة والضريبة', authority: 'ZATCA', match: 'الزكاة والضريبة (ZATCA)' },
  { key: 'customs', label: 'الجمارك (فسح)', authority: 'الجمارك السعودية', match: 'الجمارك (فسح)' },
  { key: 'balady', label: 'بلدي', authority: 'الشؤون البلدية', match: 'بلدي' },
  { key: 'civildefense', label: 'الدفاع المدني', authority: 'الدفاع المدني', match: 'الدفاع المدني (سلامة)' },
  { key: 'ejar', label: 'إيجار', authority: 'REGA', match: 'إيجار' },
  { key: 'misa', label: 'MISA الاستثمار', authority: 'MISA', match: 'MISA' },
];

const platforms = PLATFORM_DEFS.map(def => {
  const regItems = register.filter(r => r.platform === def.match);
  const alItems = alerts.filter(a => a.platform === def.match);
  const red = alItems.filter(a => a.risk === 'أحمر').length;
  const yellow = alItems.filter(a => a.risk === 'أصفر').length;
  const green = alItems.filter(a => a.risk === 'أخضر').length;
  const days = regItems.map(r => r.daysRemaining).filter(d => d !== null && d !== undefined);
  const nearestDays = days.length ? Math.min.apply(null, days) : null;
  const expired = regItems.filter(r => r.daysRemaining !== null && r.daysRemaining <= 0).length;
  return {
    key: def.key, label: def.label, authority: def.authority,
    itemCount: regItems.length, red: red + expired, yellow, green, nearestDays,
    hasData: regItems.length > 0 || alItems.length > 0,
  };
});

return [{ json: {
  ok: true,
  locked: !!auth.locked,
  company: auth.company,
  email: auth.email,
  pageId: auth.pageId,
  companies: auth.companies || [],
  status: auth.status, summary: auth.summary,
  employees: auth.employees, saudis: auth.saudis, band: auth.band,
  quarterlyCost: auth.quarterlyCost, annualCost: auth.annualCost, lastAnalysis: auth.lastAnalysis,
  healthScore: score, healthBand: band,
  counts: { red: redCount + expiredCount, yellow: yellowCount + soonCount, green: greenCount },
  alerts: auth.locked ? [] : alerts, register: auth.locked ? [] : register, platforms: auth.locked ? [] : platforms,
  files: auth.locked ? [] : files,
  generatedAt: new Date().toISOString(),
} }];
